static int char_to_index(char c) {
    if (c == '0') return 0;
    if (c == '1') return 1;
    if (c == '2') return 2;
    if (c == '3') return 3;
    if (c == '4') return 4;
    if (c == '5') return 5;
    if (c == '6') return 6;
    if (c == '7') return 7;
    if (c == '8') return 8;
    if (c == '9') return 9;
    if (c == '%') return 10;
    if (c == '.') return 11;
    if (c == ' ') return 12;
    if (c == 'A') return 13;
    if (c == 'B') return 14;
    if (c == 'C') return 15;
    if (c == 'D') return 16;
    if (c == 'E') return 17;
    if (c == 'F') return 18;
    if (c == 'G') return 19;
    if (c == 'H') return 20;
    if (c == 'I') return 21;
    if (c == 'J') return 22;
    if (c == 'K') return 23;
    if (c == 'L') return 24;
    if (c == 'M') return 25;
    if (c == 'N') return 26;
    if (c == 'O') return 27;
    if (c == 'P') return 28;
    if (c == 'Q') return 29;
    if (c == 'R') return 30;
    if (c == 'S') return 31;
    if (c == 'T') return 32;
    if (c == 'U') return 33;
    if (c == 'V') return 34;
    if (c == 'W') return 35;
    if (c == 'X') return 36;
    if (c == 'Y') return 37;
    if (c == 'Z') return 38;
    if (c == 'a') return 39;
    if (c == 'b') return 40;
    if (c == 'c') return 41;
    if (c == 'd') return 42;
    if (c == 'e') return 43;
    if (c == 'f') return 44;
    if (c == 'g') return 45;
    if (c == 'h') return 46;
    if (c == 'i') return 47;
    if (c == 'j') return 48;
    if (c == 'k') return 49;
    if (c == 'l') return 50;
    if (c == 'm') return 51;
    if (c == 'n') return 52;
    if (c == 'o') return 53;
    if (c == 'p') return 54;
    if (c == 'q') return 55;
    if (c == 'r') return 56;
    if (c == 's') return 57;
    if (c == 't') return 58;
    if (c == 'u') return 59;
    if (c == 'v') return 60;
    if (c == 'w') return 61;
    if (c == 'x') return 62;
    if (c == 'y') return 63;
    if (c == 'z') return 64;
    return -1;
}

int u8g2_font_small_draw_char(int x, int y, char c, lcd_color_t color,
                                   lcd_color_t bg, bool transparent) {
    int idx = char_to_index(c);
    if (idx < 0) return 0;
    const uint8_t *data = font_data[idx];
    for (int row = 0; row < FONT_SMALL_HEIGHT; row++) {
        for (int col = 0; col < FONT_SMALL_WIDTH; col++) {
            int px = x + col;
            int py = y + row;
            if (px < 0 || px >= LCD_WIDTH || py < 0 || py >= LCD_HEIGHT)
                continue;
            int bit_idx = row * FONT_SMALL_WIDTH + col;
            int byte_off = bit_idx / 8;
            int bit_off = 7 - (bit_idx % 8);
            if (data[byte_off] & (1 << bit_off)) {
                lcd_draw_pixel(px, py, color);
            } else if (!transparent) {
                lcd_draw_pixel(px, py, bg);
            }
        }
    }
    return font_widths[idx];
}

int u8g2_font_small_draw_string(int x, int y, const char *str,
                                    lcd_color_t color, lcd_color_t bg, bool transparent) {
    int start_x = x;
    while (*str) {
        x += u8g2_font_small_draw_char(x, y, *str, color, bg, transparent);
        str++;
    }
    return x - start_x;
}

int u8g2_font_small_string_width(const char *str) {
    int w = 0;
    while (*str) {
        int idx = char_to_index(*str);
        if (idx >= 0) w += font_widths[idx];
        str++;
    }
    return w;
}
